2. 원무 직무와 연결되는 강점이 없어 직무 적합성을 판단하기 어려워요. (C 직무·기업 연결) 글쓰기 강점을 환자 안내문 작성이나 원무·민원 소통과 연결해 말해 주세요.

바꿔 말하기: "안녕하세요, 국어국문학과 4학년 문서영입니다. 글쓰기에 대한 관심을 바탕으로 병원에서 일하기 위해 준비하고 있습니다."

