2. 지원 이유를 뒷받침할 행동이나 결과가 제시되지 않았습니다. (B 구체성·정확성) 안내·소통·행정과 관련해 본인이 한 행동과 결과를 한 가지 덧붙여 주세요.

바꿔 말하기: "한림대학교 학생으로서 한림대학교의료원이 친숙해 지원했습니다. 또한 큰 병원에서 배우고 싶다는 이유가 있습니다."

다음 꼬리질문: 한림대학교의료원 원무 직무에서 본인의 어떤 경험을 활용해 기여할 수 있는지 말씀해 주세요.

