고칠 점
1. 안내 대상과 실제 행동이 구체적이지 않아 경험의 근거가 약해요. (B 구체성·정확성) 어떤 환자에게 무엇을 확인하고 어떻게 안내했는지 한 사례로 말해 주세요.
2. 병원 행정 원무 업무에 어떻게 도움이 되는지 설명하지 않았어요. (C 직무·기업 연결) 정확한 안내와 환자 응대가 원무 업무에 어떻게 이어지는지 덧붙여 주세요.

바꿔 말하기: "외래에서 환자분들이 진료 장소를 물어보시면 길을 안내했습니다. 환자분들이 병원 안에서 필요한 곳을 찾도록 도왔다는 점에서 정확한 안내의 중요성을 배웠어요."

