고칠 점
1. 도운 내용이 구체적이지 않아 본인의 행동을 확인하기 어렵습니다. (B 구체성·정확성) 무엇을 물어보셨고 어떤 방식으로 안내했는지 한 문장으로 설명해 주세요.
2. 원무 업무에 필요한 환자 응대와 연결되지 않았습니다. (C 직무·기업 연결) 이 경험에서 배운 소통 방식을 원무 안내 업무에 어떻게 적용할지 덧붙여 주세요.

바꿔 말하기: "어르신께서 외래 위치를 물어보셔서 목적지까지 안내해 드렸고, 고맙다는 말씀을 하셔서 기억에 남았습니다. 이 경험을 바탕으로 원무 업무에서도 환자 입장에서 이해하기 쉽게 안내하겠습니다."

