('2d50272d-2551-4ca5-9878-c68edbbd2a0e',8,$q$원무과에서 하는 일을 아는 대로 말씀해 주세요.$q$,$q$음… 접수랑 수납 같은 걸 하는 걸로 알고 있습니다.$q$,51,'question',$q$총점 51.25점 · 재연습 (A 2 · B 2 · C 2 · D 2 · E 3)

잘한 점(E 전달력·태도): "접수랑 수납 같은 걸" — 핵심 업무를 짧고 이해하기 쉽게 말씀하셨습니다.

고칠 점
1. 지식형 질문에서 업무 범위와 역할 설명이 부족해 구체성이 낮습니다. (B 구체성·정확성) 접수·수납 외 업무를 2~3개 제시하고 환자 응대와 행정 처리의 목적을 덧붙여 말씀해 주세요.
2. 원무과가 하는 일을 묻는 질문에 일부 업무만 답하셨습니다. (A 질문 적합성) 정의 한 문장 뒤에 주요 업무와 실무 적용을 순서대로 설명해 주세요.

바꿔 말하기: "원무과는 환자 접수와 진료비 수납을 담당하는 부서로 알고 있습니다. 특히 접수와 수납 업무를 수행합니다."

다음 꼬리질문: 원무과의 주요 업무를 접수와 수납 외에 무엇까지 포함하는지 설명해 주세요.
[A~E 51.25점 · 재연습 · 직무·전공지식 · A 2 · B 2 · C 2 · D 2 · E 3]
