('9767baef-6e7d-4ef9-9677-d840f182cd13',0,$q$1분 동안 자기소개를 해 주세요.$q$,$q$안녕하십니까, 국어국문학과 4학년 문서영입니다. 어… 병원 행정에서 일하고 싶어서 준비하고 있습니다. 안내문 고치는 프로젝트를 했습니다.$q$,54,'question',$q$총점 53.75점 · 재연습 (A 2 · B 2 · C 2 · D 2 · E 3)

잘한 점(E 전달력·태도): "안내문 고치는 프로젝트를 했습니다." — 짧은 문장으로 경험을 분명하게 제시했습니다.

고칠 점
1. 병원 행정과 본인의 강점이 어떻게 이어지는지 드러나지 않습니다. (C 직무·기업 연결) 프로젝트에서 기른 역량이 병원 행정에 어떻게 쓰이는지 한 문장으로 연결해 주세요.
2. 프로젝트의 본인 역할과 성과가 없어 근거가 약합니다. (B 구체성·정확성) 맡은 일과 결과를 각각 한 가지씩 구체적으로 말해 주세요.

바꿔 말하기: "안녕하십니까, 국어국문학과 4학년 문서영입니다. 병원 행정에 관심을 갖고 안내문 고치는 프로젝트를 수행했으며, 여기서 기른 역량을 관련 업무에 활용하고 싶습니다."

다음 꼬리질문: 안내문 고치는 프로젝트에서 본인이 맡은 역할과 결과를 구체적으로 말씀해 주세요.
