('9767baef-6e7d-4ef9-9677-d840f182cd13',1,$q$원무팀 실습에서는 주로 어떤 일을 하셨나요?$q$,$q$어… 창구 옆에서 선생님들 일하시는 걸 보고, 안내문 정리하는 걸 조금 도와 드렸습니다.$q$,58,'followup',$q$총점 57.5점 · 보완 필요 (A 3 · B 2 · C 2 · D 2 · E 3)

잘한 점(A 질문 적합성): "안내문 정리를 조금 도와 드렸습니다" — 실습에서 수행한 업무를 질문에 맞춰 직접 언급했습니다.

고칠 점
1. 안내문 정리 경험이 원무 직무에 어떻게 도움이 되는지 드러나지 않습니다. (C 직무·기업 연결) 환자 안내와 창구 업무의 정확성·이해도에 어떤 기여를 했는지 연결해 주세요.
2. 구체적인 담당 업무와 결과가 없어 경험의 깊이를 확인하기 어렵습니다. (B 구체성·정확성) 정리한 안내문의 내용, 본인 역할, 변화나 결과를 순서대로 말씀해 주세요.

바꿔 말하기: "원무팀 실습에서는 창구 옆에서 선생님들의 업무를 관찰하며 안내문 정리를 도왔습니다. 제가 맡은 구체적인 정리 업무는 [구체적 업무]였고, 그 결과는 [수치]로 설명드릴 수 있습니다."

다음 꼬리질문: 안내문 정리에서 본인이 맡은 구체적인 부분과 그 결과를 말씀해 주세요.
