('9767baef-6e7d-4ef9-9677-d840f182cd13',4,$q$국어국문학 전공이 병원 행정에 어떻게 도움이 될까요?$q$,$q$음… 글을 잘 쓰는 게 도움이 될 것 같습니다.$q$,51,'question',$q$총점 51.25점 · 재연습 (A 2 · B 2 · C 2 · D 2 · E 3)

잘한 점(E 전달력·태도): "글을 잘 쓰는 게 도움이" — 핵심 의견을 짧고 분명하게 제시했습니다.

고칠 점
1. 구체적 근거가 없어 역량의 효과를 확인하기 어렵습니다. (B 구체성·정확성) 작성한 문서나 안내문 사례와 개선 결과를 함께 말씀해 주세요.
2. 병원 행정 업무와의 연결이 일반적인 수준에 머뭅니다. (C 직무·기업 연결) 환자 안내문, 민원 응대 등 실제 업무에 어떻게 활용할지 설명해 주세요.

바꿔 말하기: "국어국문학에서 기른 글쓰기 능력은 병원 행정의 안내문과 문서를 환자가 이해하기 쉽게 작성하는 데 도움이 될 것 같습니다."

다음 꼬리질문: 글쓰기 능력을 병원 행정의 어떤 업무에 어떻게 활용할지 구체적으로 말씀해 주세요.
