('9767baef-6e7d-4ef9-9677-d840f182cd13',5,$q$일하면서 실수를 했을 때 어떻게 하시나요?$q$,$q$어… 바로 말씀드리겠습니다.$q$,28,'question',$q$총점 27.5점 · 재연습 (A 1 · B 1 · C 1 · D 1 · E 2)

고칠 점
1. 실제 경험과 결과가 없어 신뢰를 판단하기 어렵습니다. (B 구체성·정확성) 실수 상황, 본인의 행동, 이후 결과를 한 사례로 설명해 주세요.
2. 질문의 핵심인 실수 대처 방법에 답하지 않았습니다. (A 질문 적합성) ‘먼저 무엇을 한다’처럼 대응 절차를 첫 문장에 제시해 주세요.

바꿔 말하기: "실수했을 때는 바로 말씀드리고, 상황을 정리한 뒤 필요한 조치를 하겠습니다."

다음 꼬리질문: 실수했을 때 실제로 어떻게 대처했는지 사례와 결과를 말씀해 주세요.
