update interview_records r set ae_report = $q${"n": 7, "avg": {"A": 2.14, "B": 1.57, "C": 1.43, "D": 1.86, "E": 2.86}, "total": 46.07, "grade": "재연습", "weakest": "C", "types": ["인성·가치관", "지원동기"]}$q$::jsonb,
  score = (select case when nv is null then 46 else floor(46 * 0.9 + nv * 0.1 + 0.5)::int end from (
    select greatest(0, least(100, round(0.6*coalesce((o->>'frontPct')::numeric,0) + 0.25*(100-coalesce((o->>'downPct')::numeric,0)) + 0.15*(100-coalesce((o->>'awayPct')::numeric,0))
      - case when o->>'handPct' is not null then least(15, (o->>'handPct')::numeric*0.3) else 0 end - least(10, coalesce((o->>'movePct')::numeric,0)*0.2)
      - case when coalesce((o->>'multiPct')::numeric,0) >= 5 then 5 else 0 end - case when coalesce((o->>'lowPct')::numeric,0) >= 50 then 3 else 0 end))) nv
    from (select r.nonverbal o) z where coalesce((r.nonverbal->>'frames')::int,0) > 0) s)
  where id = '9767baef-6e7d-4ef9-9677-d840f182cd13';
