고칠 점
1. 활동의 구체성이 없어 본인의 역량을 확인하기 어렵습니다. (B 구체성·정확성) 맡은 역할과 행동, 결과를 한 가지 사례로 제시해 주세요.
2. 직무 연결 점수가 크게 부족해 행정직에 필요한 강점이 보이지 않습니다. (C 직무·기업 연결) 홍보단 활동에서 발휘한 강점을 행정 업무와 직접 연결해 말씀해 주세요.

바꿔 말하기: "안녕하십니까, 국어국문학과 4학년 문서영입니다. 심사평가원 홍보단 활동을 바탕으로 공공기관에서 일하고 싶은 지원자입니다."

