2. 좋은 일이라고 느낀 구체적 근거가 제시되지 않았습니다. (B 구체성·정확성) 홍보단 활동에서 알게 된 내용이나 본인이 확인한 사례를 하나 제시해 주세요.

바꿔 말하기: "홍보단 활동을 하면서 심사평가원을 알게 됐고, 국민에게 도움이 되는 기관이라고 생각해 지원했습니다."

