('f4384478-5753-4b7e-9d6f-9ee759c1d81e',5,$q$심사평가원이 하는 일을 아는 대로 말씀해 주세요.$q$,$q$음… 병원에서 청구한 진료비를 심사하는 일을 하는 걸로 알고 있습니다. 그리고… 평가도 하는 것 같습니다.$q$,44,'question',$q$총점 43.75점 · 재연습 (A 2 · B 2 · C 1 · D 2 · E 3)

잘한 점(E 전달력·태도): "병원에서 청구한 진료비를 심사" — 질문의 핵심인 주요 업무를 짧게 언급해 답변 방향은 잡았습니다.

고칠 점
1. 지원 직무와 국민 편익에 대한 연결이 없어 직무 적합성이 드러나지 않습니다. (C 직무·기업 연결) 행정직에서 정확한 자료 관리와 민원 안내로 어떻게 기여할지 덧붙여 주세요.
2. 심사와 평가의 의미가 구체적이지 않아 기관 이해를 확인하기 어렵습니다. (B 구체성·정확성) 각 업무가 무엇을 대상으로 어떻게 이루어지는지 한 문장씩 설명해 주세요.

바꿔 말하기: "심사평가원은 병원이 청구한 진료비를 심사하고, 의료서비스를 평가하는 기관으로 알고 있습니다. 행정직으로서 관련 자료와 민원 안내를 정확하게 관리해 국민이 제도를 이해하도록 돕겠습니다."

다음 꼬리질문: 심사평가원의 주요 업무를 두 가지로 나누고 행정직의 기여까지 말씀해 주세요.

확인 필요: 심사평가원의 진료비 심사·의료서비스 평가 업무 범위는 최신 공식 자료 확인이 필요합니다. — 확인할 수 없는 사실이라 점수에는 넣지 않았어요.
