('f4384478-5753-4b7e-9d6f-9ee759c1d81e',6,$q$업무가 몰려서 마감을 지키기 어렵다면 어떻게 하시겠어요?$q$,$q$어… 급한 것부터 하겠습니다.$q$,43,'question',$q$총점 42.5점 · 재연습 (A 2 · B 1 · C 1 · D 2 · E 3)

잘한 점(E 전달력·태도): "급한 것부터 하겠습니다." — 짧게 우선순위에 대한 본인의 방향을 먼저 제시했습니다.

고칠 점
1. 우선순위만 말해 실제 대응 과정을 확인하기 어렵습니다. (D 논리 구조) 마감과 중요도 판단 후 사실 확인, 보고·협의, 실행 순서로 설명해 주세요.
2. 판단 기준이나 행동의 근거가 없어 구체성이 부족합니다. (B 구체성·정확성) 업무를 나누는 기준과 지연이 예상될 때 취할 조치를 함께 말해 주세요.

바꿔 말하기: "업무가 몰리면 마감일과 중요도를 기준으로 우선순위를 정하겠습니다. 지연이 예상되는 업무는 즉시 공유해 조정하고, 합의한 순서대로 처리하겠습니다."

다음 꼬리질문: 마감과 중요도가 같은 업무가 여러 개라면 어떤 기준으로 우선순위를 정할지 말씀해 주세요.
