잘한 점(A 질문 적합성): "홍보 쪽 일을 하고 싶습니다" — 희망하는 업무를 첫 문장에 분명히 밝혀 질문에는 직접 답했어요.

고칠 점
1. 경험과 결과가 없어 홍보 업무 역량을 확인하기 어려워요. (B 구체성·정확성) 관련 경험에서 본인의 행동과 결과를 한 가지 덧붙여 말씀해 주세요.
2. 행정직의 실제 업무와 기관의 공공성에 연결되지 않았어요. (C 직무·기업 연결) 홍보 업무가 국민에게 어떤 편익을 주는지와 본인의 기여 방안을 연결해 주세요.

바꿔 말하기: "행정직으로 입사하면 홍보 업무를 하고 싶습니다. 특히 [담당하고 싶은 홍보 업무]를 맡아 [국민에게 제공할 편익과 기여 방식]을 실천하고 싶습니다."

다음 꼬리질문: 홍보 업무와 관련해 본인이 해 본 행동과 그 결과를 구체적으로 말씀해 주세요.
