고칠 점
1. 경험의 본인 역할과 결과가 없어 강점의 근거가 약합니다. (B 구체성·정확성) 프로젝트와 실습에서 맡은 일, 개선한 내용과 결과를 각각 구체적으로 말해 주세요.
2. 직무에서 강점을 어떻게 활용할지 설명이 부족합니다. (C 직무·기업 연결) 안내문 개선 역량이 원무의 환자 안내와 민원 응대에 어떻게 기여하는지 덧붙여 주세요.

바꿔 말하기: "안녕하십니까, 국어국문학과 4학년 문서영입니다. 저는 안내문을 쉽게 고치는 강점이 있으며, 병원 안내문 프로젝트와 원무팀 실습을 경험했습니다. 이 강점을 환자 안내와 원무 업무에 활용하겠습니다."

다음 꼬리질문: 안내문 프로젝트와 원무팀 실습에서 본인이 맡은 일과 결과를 구체적으로 말씀해 주세요.
