고칠 점
1. 본인이 무엇을 어떻게 했는지와 결과가 없어 경험의 근거가 약합니다. (B 구체성·정확성) 담당 상황, 본인 행동, 개선된 결과를 구체적으로 덧붙여 말씀해 주세요.
