잘한 점(E 전달력·태도): "선임 선생님께 도움을 요청하겠습니다" — 짧고 명확하게 다음 행동을 제시했습니다.

고칠 점
1. 상황대처의 핵심인 단계별 판단 과정이 빠졌습니다. (D 논리 구조) 설명 재확인, 선임 보고·협의, 이후 대응 순서로 말해 주세요.
2. 왜 도움을 요청하는지와 기대하는 결과가 드러나지 않습니다. (B 구체성·정확성) 환자의 이해 여부를 확인하고 정확한 안내를 위해 요청한다고 덧붙여 주세요.

바꿔 말하기: "설명을 했는데도 환자가 받아들이지 않으면, 먼저 이해하지 못한 부분을 확인하겠습니다. 그래도 어렵다면 정확한 안내를 위해 선임 선생님께 도움을 요청하겠습니다."

