고칠 점
1. 주의점 하나만 제시해 개인정보 처리의 정확한 기준을 확인하기 어렵습니다. (B 구체성·정확성) 접근 권한, 본인 확인, 화면·서류 노출 방지 등 핵심 원칙을 2~3개 말해 주세요.
2. 답변의 범위가 좁아 지식 질문에 대한 논리적 설명이 부족합니다. (D 논리 구조) 정의 한 문장 뒤에 원칙과 원무 창구에서의 적용 순서로 답해 주세요.

바꿔 말하기: "원무 업무에서는 개인정보가 다른 사람에게 들리지 않도록 조심해야 합니다."

다음 꼬리질문: 개인정보 보호 원칙을 정의, 핵심 주의점, 원무 창구 적용 순서로 말씀해 주세요.
