잘한 점(A 질문 적합성): "서로 잘 도와주는 사람이 좋습니다" — 함께 일하고 싶은 동료의 기준을 첫 문장에 분명히 제시했습니다.

고칠 점
1. 구체적 경험이 없어 협업 기준의 진정성을 확인하기 어렵습니다. (B 구체성·정확성) 팀 프로젝트나 실습에서 서로 도운 행동과 결과를 한 가지 말씀해 주세요.
2. 원무 업무의 협업과 환자 응대에 연결되지 않았습니다. (C 직무·기업 연결) 동료와 협력할 때 환자 안내나 업무 정확성에 어떤 도움이 되는지 덧붙여 주세요.

바꿔 말하기: "함께 일하고 싶은 동료는 서로 돕는 사람입니다. 원무 업무에서는 동료와 필요한 내용을 정확히 공유하고 협력해 환자 안내가 혼선 없이 이루어지도록 하겠습니다."

다음 꼬리질문: 서로 도와서 업무나 문제를 해결했던 구체적인 경험을 말씀해 주세요.
