      - case when o->>'handPct' is not null then least(15, (o->>'handPct')::numeric*0.3) else 0 end - least(10, coalesce((o->>'movePct')::numeric,0)*0.2)
      - case when coalesce((o->>'multiPct')::numeric,0) >= 5 then 5 else 0 end - case when coalesce((o->>'lowPct')::numeric,0) >= 50 then 3 else 0 end))) nv
    from (select r.nonverbal o) z where coalesce((r.nonverbal->>'frames')::int,0) > 0) s)
  where id = '9ccbecb8-94e5-4ee9-812c-a1e00d951d71';
