잘한 점(A 질문 적합성): "저는 어려운 글을 쉽게 바꾸는 걸 잘합니다." — 첫 문장에서 자신의 핵심 강점을 분명하게 제시하셨습니다.

고칠 점
1. 직무와 회사에 연결한 설명이 없어 지원 방향이 흐려집니다. (C 직무·기업 연결) 병원 안내문 개선 역량을 보건의료 행정 업무와 연결해 마무리해 주세요.
2. 프로젝트와 홍보단의 본인 역할·성과가 없어 근거가 약합니다. (B 구체성·정확성) 맡은 일과 결과를 각각 한 가지씩 수치와 함께 제시해 주세요.

바꿔 말하기: "저는 어려운 글을 쉽게 바꾸는 강점이 있습니다. 병원 안내문 개선 프로젝트에서 [수치]를 맡아 수행했고, 심사평가원 홍보단 경험도 바탕으로 보건의료 행정 업무에 기여하겠습니다."

다음 꼬리질문: 병원 안내문 개선 프로젝트에서 본인 역할과 결과를 직무와 연결해 말씀해 주세요.
[A~E 61.25점 · 보완 필요 · 자기소개 · A 3 · B 2 · C 2 · D 3 · E 3]
[리포트 B · 내용 61 · 구조 47 · 구체성 42 · 분량 40 · 태도·언어 88]
[전달력 92점] 말하기 속도 225자/분(적당) · 군말 없음 · 답변 18초(조금 짧음) · 머뭇거림 0.9초$q$,(select created_at from interview_records where id='81e80db7-5ea5-4afc-b9ce-231e1c06c640') - interval '208 seconds'),
('81e80db7-5ea5-4afc-b9ce-231e1c06c640',1,$q$안내문 12종을 고칠 때 가장 신경 쓴 점은 무엇인가요?$q$,$q$음… 문장을 짧게 하고, 어려운 말은 쉬운 말로 바꿨습니다.$q$,69,'followup',$q$총점 68.75점 · 보완 필요 (A 4 · B 2 · C 2 · D 3 · E 4)

잘한 점(A 질문 적합성): "문장을 짧게 하고" — 질문한 핵심 기준을 첫 문장부터 분명하게 답하셨습니다.

고칠 점
1. 직무 연결이 없어 지원 분야에서의 의미가 드러나지 않습니다. (C 직무·기업 연결) 환자 안내와 원무·민원 업무에 어떤 도움이 되는지 덧붙여 주세요.
2. 실제 적용 방식과 결과가 없어 설명의 설득력이 약합니다. (B 구체성·정확성) 본인이 맡은 문안 작성 과정과 이해도 변화 등 확인 가능한 근거를 제시해 주세요.

바꿔 말하기: "안내문을 고칠 때는 문장을 짧게 하고 어려운 말을 쉬운 말로 바꾸는 데 가장 신경 썼습니다. 이렇게 환자가 안내 내용을 한 번에 이해하도록 했습니다."

다음 꼬리질문: 쉬운 말로 바꾸기 위해 본인이 적용한 기준과 결과를 구체적으로 말씀해 주세요.
[A~E 68.75점 · 보완 필요 · 자기소개 · A 4 · B 2 · C 2 · D 3 · E 4]
[리포트 C · 내용 65 · 구조 17 · 구체성 32 · 분량 36 · 태도·언어 88]
[전달력 82점] 말하기 속도 232자/분(적당) · 군말 1회 · 답변 6초(짧음) · 머뭇거림 1.3초$q$,(select created_at from interview_records where id='81e80db7-5ea5-4afc-b9ce-231e1c06c640') - interval '176 seconds'),
('81e80db7-5ea5-4afc-b9ce-231e1c06c640',2,$q$팀으로 일하면서 성과를 낸 경험을 말씀해 주세요.$q$,$q$홍보단에서 팀으로 카드뉴스를 만들었습니다. 저는 글을 맡았고, 어… 저희 팀이 우수 활동팀이 됐습니다.$q$,51,'question',$q$총점 51.25점 · 재연습 (A 3 · B 2 · C 1 · D 2 · E 3)

잘한 점(E 전달력·태도): "우수 활동팀이 됐습니다" — 팀의 결과를 짧고 분명하게 제시하셨습니다.

고칠 점
1. 본인이 한 글 작성 행동과 팀 성과의 근거가 구체적이지 않습니다. (B 구체성·정확성) 작성한 내용, 협업 방식, 결과를 순서대로 말하고 가능한 수치를 제시해 주세요.
2. 직무 연결이 없어 지원 분야에서의 활용 가능성이 보이지 않습니다. (C 직무·기업 연결) 카드뉴스 제작 경험이 보건의료 행정의 안내문 작성에 어떻게 이어지는지 덧붙여 주세요.

바꿔 말하기: "홍보단에서 팀으로 카드뉴스를 만들 때 저는 글 작성을 맡았습니다. 팀은 우수 활동팀으로 선정됐고, 이 경험을 바탕으로 보건의료 행정에서도 이해하기 쉬운 안내문을 작성하겠습니다."

다음 꼬리질문: 카드뉴스 글을 작성할 때 본인이 한 구체적인 행동과 결과를 말씀해 주세요.
[A~E 51.25점 · 재연습 · 경험·역량 · A 3 · B 2 · C 1 · D 2 · E 3]
[리포트 C · 내용 51 · 구조 39 · 구체성 39 · 분량 23 · 태도·언어 88]
[전달력 82점] 말하기 속도 239자/분(적당) · 군말 1회 · 답변 10초(짧음) · 머뭇거림 1.6초$q$,(select created_at from interview_records where id='81e80db7-5ea5-4afc-b9ce-231e1c06c640') - interval '139 seconds'),
('81e80db7-5ea5-4afc-b9ce-231e1c06c640',3,$q$우수 활동팀이 된 데에 본인은 어떤 기여를 했나요?$q$,$q$어려운 말을 쉽게 바꾸는 걸 했습니다.$q$,46,'followup',$q$총점 46.25점 · 재연습 (A 2 · B 1 · C 2 · D 2 · E 4)

잘한 점(E 전달력·태도): "어려운 말을 쉽게 바꾸는 걸 했습니다." — 핵심 활동을 군더더기 없이 간결하게 전달했습니다.

고칠 점
1. 행동과 결과가 없어 본인 기여를 판단하기 어렵습니다. (B 구체성·정확성) 어떤 표현을 어떻게 바꾸었고 팀 결과에 어떤 영향을 줬는지 말해 주세요.
2. 글 작성 경험이 지원 직무에 어떻게 쓰이는지 빠졌습니다. (C 직무·기업 연결) 쉬운 문서 작성 역량을 지원 직무의 안내·소통 업무와 연결해 주세요.

바꿔 말하기: "저는 카드뉴스에서 어려운 말을 쉽게 바꾸는 글 작업을 맡았습니다. 그 결과 우수 활동팀 선정에 기여했으며, 지원 직무에서도 이해하기 쉬운 안내문을 작성하겠습니다."

다음 꼬리질문: 어려운 말을 쉽게 바꾸기 위해 어떤 표현을 어떻게 수정했는지 구체적으로 말씀해 주세요.
[A~E 46.25점 · 재연습 · 경험·역량 · A 2 · B 1 · C 2 · D 2 · E 4]
[리포트 D · 내용 46 · 구조 17 · 구체성 30 · 분량 23 · 태도·언어 88]
[전달력 82점] 말하기 속도 246자/분(측정하기엔 짧음) · 군말 없음 · 답변 4초(짧음) · 머뭇거림 2.0초$q$,(select created_at from interview_records where id='81e80db7-5ea5-4afc-b9ce-231e1c06c640') - interval '108 seconds'),
('81e80db7-5ea5-4afc-b9ce-231e1c06c640',4,$q$공공기관 행정직에게 필요한 역량은 무엇이라고 생각하시나요?$q$,$q$정확하게 일하는 것과 잘 설명하는 것이 필요하다고 생각합니다.$q$,55,'question',$q$총점 55점 · 보완 필요 (A 3 · B 2 · C 2 · D 2 · E 2)

잘한 점(A 질문 적합성): "정확하게 일하는 것" — 질문에 맞춰 필요한 역량을 두 가지로 바로 제시했습니다.

고칠 점
1. 근거가 없어 역량의 실제 발휘 수준을 확인하기 어렵습니다. (B 구체성·정확성) 본인이 맡은 행동과 그 결과가 드러나는 경험을 덧붙여 말씀해 주세요.
2. 공공기관 행정직의 정확성과 설명 역량이 어떤 업무에 쓰이는지 보이지 않습니다. (C 직무·기업 연결) 민원 응대나 문서 처리 등 직무 상황과 연결해 설명해 주세요.

바꿔 말하기: "공공기관 행정직에는 정확하게 일하는 역량과 잘 설명하는 역량이 필요하다고 생각합니다. 두 역량이 필요한 이유와 실제 적용 사례를 함께 말씀드리겠습니다."

다음 꼬리질문: 정확하게 일하거나 잘 설명한 경험과 그 결과를 공공기관 행정 업무와 연결해 말씀해 주세요.
[A~E 55점 · 보완 필요 · 직무·전공지식 · A 3 · B 2 · C 2 · D 2 · E 2]
[리포트 C · 내용 55 · 구조 39 · 구체성 28 · 분량 21 · 태도·언어 88]
[전달력 82점] 말하기 속도 253자/분(적당) · 군말 없음 · 답변 6초(짧음) · 머뭇거림 2.4초$q$,(select created_at from interview_records where id='81e80db7-5ea5-4afc-b9ce-231e1c06c640') - interval '74 seconds'),
('81e80db7-5ea5-4afc-b9ce-231e1c06c640',5,$q$규칙과 융통성 중 무엇이 더 중요하다고 보시나요?$q$,$q$규칙이 먼저라고 생각합니다. 어… 그래도 국민이 덜 불편하게 안내할 수는 있다고 생각합니다.$q$,68,'question',$q$총점 67.5점 · 보완 필요 (A 4 · B 2 · C 2 · D 3 · E 2)

잘한 점(A 질문 적합성): "규칙이 먼저라고 생각합니다" — 질문의 선택지에 대해 첫 문장으로 입장을 분명히 밝히셨습니다.

고칠 점
1. 사례와 판단 기준이 없어 주장의 설득력이 낮습니다. (B 구체성·정확성) 규칙과 융통성 사이에서 판단했던 실제 상황과 본인의 행동을 덧붙여 주세요.
2. 국민 불편이라는 표현만으로는 직무에서 어떻게 적용할지 부족합니다. (C 직무·기업 연결) 안내·원무 업무에서 규칙을 지키며 불편을 줄이는 방법으로 연결해 주세요.

바꿔 말하기: "규칙이 먼저라고 생각합니다. 다만 국민의 불편을 줄일 수 있다면 규정의 취지를 벗어나지 않는 범위에서 융통성을 발휘하겠습니다."

다음 꼬리질문: 규칙을 지키면서도 융통성을 발휘했던 실제 상황과 본인의 행동을 말씀해 주세요.
[A~E 67.5점 · 보완 필요 · 인성·가치관 · A 4 · B 2 · C 2 · D 3 · E 2]
[리포트 C · 내용 65 · 구조 39 · 구체성 32 · 분량 31 · 태도·언어 88]
[전달력 82점] 말하기 속도 260자/분(적당) · 군말 1회 · 답변 9초(짧음) · 머뭇거림 2.8초$q$,(select created_at from interview_records where id='81e80db7-5ea5-4afc-b9ce-231e1c06c640') - interval '37 seconds'),
('81e80db7-5ea5-4afc-b9ce-231e1c06c640',6,$q$마지막으로 하고 싶은 말이 있나요?$q$,$q$더 준비해서 좋은 행정 직원이 되겠습니다. 감사합니다.$q$,53,'question',$q$총점 52.5점 · 재연습 (A 3 · B 1 · C 1 · D 2 · E 4)

잘한 점(E 전달력·태도): "감사합니다." — 불필요한 설명 없이 짧고 명확하게 마무리했습니다.

고칠 점
1. 직무와 연결된 메시지가 없어 가장 큰 배점 손실이 있습니다. (C 직무·기업 연결) 지원 직무에서 발휘할 본인의 강점을 한 문장으로 덧붙여 주세요.
2. 강점을 뒷받침할 경험이나 결과가 없습니다. (B 구체성·정확성) 면접에서 말한 경험 중 하나와 얻은 결과를 짧게 제시해 주세요.

바꿔 말하기: "오늘 말씀드린 강점을 바탕으로 더 준비해 좋은 행정 직원이 되겠습니다. 감사합니다."

다음 꼬리질문: 지원 직무에서 발휘할 본인의 강점과 그 근거를 한 가지 말씀해 주세요.
[A~E 52.5점 · 재연습 · 마무리 · A 3 · B 1 · C 1 · D 2 · E 4]
[리포트 D · 내용 53 · 구조 51 · 구체성 35 · 분량 40 · 태도·언어 88]
