insert into interview_answers (record_id,question_index,question_text,answer_text,score,kind,feedback,created_at) values
('4f6f72d8-13ae-49b5-abf5-f17560f0a68b',0,$q$1분 동안 자기소개를 해 주세요.$q$,$q$안녕하십니까, 국어국문학과 4학년 문서영입니다. 저는 환자가 이해하기 쉬운 안내를 만드는 일을 해 봤습니다. 병원 안내문 프로젝트와 원무팀 실습을 했습니다.$q$,65,'question',$q$총점 65점 · 보완 필요 (A 3 · B 2 · C 3 · D 2 · E 3)

잘한 점(C 직무·기업 연결): "원무팀 실습을 했습니다" — 병원 안내와 원무팀 실습을 언급해 지원 직무와의 관련성을 보여 주셨습니다.

고칠 점
1. 경험의 본인 역할과 성과가 없어 근거가 약합니다. (B 구체성·정확성) 각 경험에서 맡은 일과 결과를 한 문장씩 덧붙여 주세요.
2. 핵심 강점 뒤에 경험·직무 연결·포부가 이어지지 않습니다. (D 논리 구조) 강점→구체적 경험→원무 직무 기여→포부 순서로 구성해 주세요.

바꿔 말하기: "저는 환자가 이해하기 쉬운 안내를 만드는 사람입니다. 병원 안내문 프로젝트와 원무팀 실습 경험을 바탕으로, 병원 행정에서 환자에게 정확하고 이해하기 쉬운 안내를 제공하겠습니다."

다음 꼬리질문: 방금 말씀한 병원 안내문 프로젝트에서 본인이 맡은 역할과 결과를 구체적으로 말씀해 주세요.
