('4f6f72d8-13ae-49b5-abf5-f17560f0a68b',8,$q$건강보험 제도에서 본인부담금이 무엇인지 설명해 주세요.$q$,$q$진료비 중에서 건강보험이 내는 부분을 빼고 환자가 직접 내는 돈으로 알고 있습니다. 외래나 입원에 따라 비율이 다른 걸로 알고 있습니다.$q$,76,'question',$q$총점 76.25점 · 양호 (A 4 · B 3 · C 2 · D 3 · E 4)

잘한 점(A 질문 적합성): "환자가 직접 내는 돈" — 질문의 핵심인 본인부담금의 의미를 첫 문장에 바로 답하셨어요.

고칠 점
1. 정의는 맞지만 본인부담금의 적용 범위와 기준이 충분히 구체적이지 않아요. (B 구체성·정확성) 건강보험 적용 진료비 중 환자가 부담하는 금액이라고 정확히 설명하고 진료 형태별 기준을 덧붙여 주세요.
2. 원무 직무에서 환자에게 어떻게 안내할지 연결되지 않았어요. (C 직무·기업 연결) 창구에서 진료 항목과 적용 기준을 확인해 환자에게 정확히 안내하겠다고 말해 주세요.

바꿔 말하기: "본인부담금은 건강보험이 적용되는 진료비 중 환자가 부담하는 금액입니다. 외래·입원 등 진료 형태와 적용 기준을 확인해 원무 창구에서 환자에게 정확히 안내하겠습니다."

다음 꼬리질문: 원무 창구에서 본인부담금을 안내할 때 무엇을 먼저 확인할지 말씀해 주세요.
