('9d50a7aa-fe65-4c20-9242-4b7aec6078ed',0,$q$1분 동안 자기소개를 해 주세요.$q$,$q$안녕하십니까, 국어국문학과 4학년 문서영입니다. 저는 어려운 제도를 쉽게 전하는 걸 잘합니다. 심사평가원 홍보단에서 콘텐츠를 만들었고, 병원 안내문 프로젝트도 했습니다.$q$,61,'question',$q$총점 61.25점 · 보완 필요 (A 3 · B 2 · C 2 · D 2 · E 4)

잘한 점(E 전달력·태도): "어려운 제도를 쉽게 전하는" — 핵심 강점을 첫부분에 짧고 분명하게 제시했습니다.

고칠 점
1. 행정직에서 그 강점을 어떻게 활용할지 드러나지 않아 직무 연결 점수를 잃었습니다. (C 직무·기업 연결) 경험을 국민 대상 안내·문서 업무와 연결해 한 문장으로 마무리해 주세요.
2. 두 경험의 본인 역할과 결과가 없어 강점의 근거가 약합니다. (B 구체성·정확성) 각 경험에서 맡은 일과 변화된 결과를 구체적으로 덧붙여 주세요.

바꿔 말하기: "안녕하십니까, 국어국문학과 4학년 문서영입니다. 저는 어려운 제도를 쉽게 전하는 강점이 있으며, 심사평가원 홍보단 콘텐츠 제작과 병원 안내문 프로젝트 경험을 통해 이를 실천했습니다."

다음 꼬리질문: 병원 안내문 프로젝트에서 본인이 맡은 역할과 결과를 구체적으로 말씀해 주세요.
