[전달력 82점] 말하기 속도 239자/분(측정하기엔 짧음) · 군말 없음 · 답변 4초(짧음) · 머뭇거림 1.6초$q$,(select created_at from interview_records where id='9d50a7aa-fe65-4c20-9242-4b7aec6078ed') - interval '272 seconds'),
