잘한 점(A 질문 적합성): "병원 평가 결과 찾는 방법" — 질문한 콘텐츠를 첫 문장에 제시해 답변 초점을 분명히 했습니다.

고칠 점
1. 가중치가 큰 구체성에서 결과가 없어 실제 성과를 확인하기 어렵습니다. (B 구체성·정확성) 카드뉴스를 만든 본인 행동과 게시 후 반응·조회 수 등 결과를 덧붙여 주세요.
2. 행정직에서 필요한 국민 안내와 정보 전달 역량으로 이어지지 않았습니다. (C 직무·기업 연결) 어려운 정보를 쉽게 전달한 경험이 공공기관 행정 업무에 어떻게 쓰이는지 연결해 주세요.

바꿔 말하기: "가장 기억에 남는 콘텐츠는 병원 평가 결과를 찾는 방법을 안내한 카드뉴스입니다. 어려운 용어를 쉽게 바꿔 국민이 정보를 이해하기 쉽도록 만들었고, 결과는 [수치]로 확인했습니다."

다음 꼬리질문: 카드뉴스 제작 과정에서 본인이 구체적으로 한 행동과 제작 후 결과를 수치로 말씀해 주세요.
