('9d50a7aa-fe65-4c20-9242-4b7aec6078ed',4,$q$쉬운 말 목록은 어떻게 만들었나요?$q$,$q$음… 어려운 용어를 골라서 쉬운 말로 바꿨습니다.$q$,59,'followup',$q$총점 58.75점 · 보완 필요 (A 3 · B 2 · C 2 · D 2 · E 4)

잘한 점(E 전달력·태도): "쉬운 말로 바꿨습니다" — 핵심 행동을 짧고 분명하게 전달했어요.

고칠 점
1. 어려운 용어를 고른 기준과 바꾼 결과가 없어 구체성이 낮아요. (B 구체성·정확성) 용어 선정 기준, 변경 예시, 확인한 결과를 차례로 말씀해 주세요.
2. 쉬운 안내가 행정직의 국민 소통 업무와 어떻게 이어지는지 부족해요. (C 직무·기업 연결) 국민이 정보를 정확히 이해하도록 돕는 직무 역량으로 연결해 주세요.

바꿔 말하기: "환자가 이해하기 어려운 용어를 먼저 골라 일상적인 표현으로 바꿨습니다. 바꾼 문안은 [수치]명에게 확인해 이해하기 쉬운지 점검했습니다."

다음 꼬리질문: 어떤 기준으로 어려운 용어를 골랐고, 바꾼 뒤 이해도를 어떻게 확인했는지 말씀해 주세요.
