잘한 점(A 질문 적합성): "먼저 이야기를 끝까지 듣고" — 항의 상황에서 상대방의 말을 먼저 듣겠다는 대응 방향을 분명히 제시하셨습니다.

고칠 점
1. 판단 기준과 후속 절차가 없어 대응의 신뢰성이 약해집니다. (D 논리 구조) 사실 확인, 기준 검토, 담당 부서 협의, 결과 안내 순서로 말해 주세요.
2. 행정직으로서 공정한 평가 안내와 민원 처리 역할이 드러나지 않습니다. (C 직무·기업 연결) 관련 기준에 따라 공정하게 확인하고 공식 절차로 안내하겠다고 연결해 주세요.

바꿔 말하기: "먼저 담당자의 말씀을 끝까지 듣고 평가 결과에 대한 쟁점을 확인하겠습니다. 이후 관련 기준과 절차를 검토해 담당 부서와 협의하고, 가능한 조치와 안내 내용을 정리해 다시 설명드리겠습니다."

다음 꼬리질문: 담당 부서와 협의해도 담당자가 계속 항의한다면 어떤 기준으로 다음 조치를 하실지 말씀해 주세요.
