잘한 점(E 전달력·태도): "정확하고 쉽게 쓰는 게 중요" — 핵심 원칙을 군더더기 없이 분명하게 제시했습니다.

고칠 점
1. 왜 — 정확성과 쉬운 표현이 중요한 이유와 적용 근거가 빠졌습니다. (B 구체성·정확성) 어떻게 — 원칙을 지키기 위한 기준이나 문서 작성 사례를 덧붙여 주세요.
2. 왜 — 공공기관 행정 문서가 국민에게 미치는 영향이 연결되지 않았습니다. (C 직무·기업 연결) 어떻게 — 국민이 내용을 오해하지 않고 업무를 처리하도록 돕는 점을 설명해 주세요.

바꿔 말하기: "공공기관 문서는 정확하고 쉽게 쓰는 것이 가장 중요하다고 생각합니다. 국민이 내용을 오해하지 않도록 핵심 정보를 정확히 전달하고, 어려운 표현은 이해하기 쉬운 말로 바꾸겠습니다."

다음 꼬리질문: 정확하고 쉬운 문서를 작성하기 위해 실제로 어떤 기준이나 절차를 적용할지 말씀해 주세요.
