고칠 점
1. 사례와 행동이 없어 공정성을 실제로 실천할 수 있는지 확인하기 어렵습니다. (B 구체성·정확성) 공정성을 지킨 경험에서 본인의 행동과 결과를 한 가지 덧붙여 말씀해 주세요.
2. 결론 뒤에 근거와 입사 후 실천 방법이 이어지지 않았습니다. (D 논리 구조) 원칙, 사례, 행정 업무에서의 실천 순서로 1분 안에 답변해 주세요.

바꿔 말하기: "공정하게 일하고 싶습니다. 행정 업무에서 기준과 근거를 확인하고, 이해관계와 관계없이 같은 절차로 처리하겠습니다."

