고칠 점
1. 지원 기관과 행정직에서의 역할 연결이 없어 차별성이 약합니다. (C 직무·기업 연결) 건강보험심사평가원 행정 업무에서 국민에게 정보를 쉽게 전달하겠다고 구체화해 주세요.
