잘한 점(B 구체성·정확성): "안내문을 쉬운 말로 고쳤고" — 직무와 관련된 두 경험을 간결하게 제시했습니다.

고칠 점
1. 원무 직무에서 강점을 어떻게 활용할지 설명이 부족합니다. (C 직무·기업 연결) 환자 안내와 문서 정리 역량이 원무 업무에 어떻게 기여하는지 한 문장으로 연결해 주세요.
2. 경험에서 맡은 역할과 결과가 드러나지 않습니다. (B 구체성·정확성) 본인이 한 행동과 개선 결과를 각각 한 가지씩 구체적으로 덧붙여 주세요.

바꿔 말하기: "저는 어려운 안내를 쉽게 바꾸는 강점이 있습니다. 캡스톤 프로젝트에서 병원 안내문을 쉬운 말로 고쳤고, 춘천성심병원 원무팀 실습에서는 안내문 정리를 도왔습니다. 이 강점을 바탕으로 환자 안내와 원무 문서 업무에 기여하겠습니다."

