고칠 점
1. 병원 특징이 원무 업무에 어떻게 연결되는지 드러나지 않습니다. (C 직무·기업 연결) 병원별 특성이 환자 안내·접수·민원 업무에 미칠 영향을 본인 역할과 연결해 주세요.
2. 최근 노력이나 사업을 말하지 않아 회사 이해의 근거가 부족합니다. (B 구체성·정확성) 최근 확인한 노력이나 사업을 1~2개 골라 출처와 함께 설명해 주세요.

바꿔 말하기: "한림대학교의료원은 춘천·평촌·강남·한강·동탄에 병원이 있고, 한강성심병원은 화상 치료로 알려져 있다고 알고 있습니다. 원무 업무에서는 병원별 특징을 정확히 파악해 환자 안내와 접수에 반영하겠습니다."

다음 꼬리질문: 말씀하신 병원 특징을 원무 직무에서 어떻게 활용할지 말씀해 주세요.

