잘한 점(A 질문 적합성): "정확해야 합니다" — 정확성이 왜 필요한지 첫 문장에 분명히 제시했습니다.

고칠 점
1. 일반적인 결과만 있어 정확성의 근거와 실무성이 약합니다. (B 구체성·정확성) 진료비 처리에서 확인할 항목이나 오류를 막은 사례를 덧붙여 주세요.
2. 정의와 핵심 원리, 적용 예시의 흐름이 빠져 있습니다. (D 논리 구조) 정확성의 의미→오류 위험→확인·보고·기록 순서로 답해 주세요.

바꿔 말하기: "원무 업무의 정확성은 환자 정보와 진료비를 올바르게 처리하기 위해 중요합니다. 정보가 틀리면 진료비 처리가 잘못될 수 있으므로, 확인할 내용을 점검한 뒤 정확하게 처리하겠습니다."

다음 꼬리질문: 진료비 처리가 잘못되지 않도록 원무 담당자가 무엇을 먼저 확인해야 하는지 말씀해 주세요.
