잘한 점(E 전달력·태도): "감사합니다." — 짧고 명확하게 마무리해 전달력이 좋습니다.

고칠 점
1. 환자 안내만 제시해 원무 직무에서의 역할이 드러나지 않습니다. (C 직무·기업 연결) 접수·수납·민원 안내와 연결해 어떤 직원이 될지 덧붙여 주세요.
2. 강점을 뒷받침할 본인의 행동이나 결과가 빠져 있습니다. (B 구체성·정확성) 면접에서 말한 경험 중 하나를 짧게 근거로 제시해 주세요.

바꿔 말하기: "감사합니다. 환자분들께 쉬운 안내를 드리는 직원이 되겠다는 강점을 바탕으로, 원무 업무에서도 정확하고 이해하기 쉬운 안내를 실천하겠습니다."

다음 꼬리질문: 환자에게 쉬운 안내를 제공하기 위해 본인이 실제로 한 행동과 결과를 말씀해 주세요.
