바꿔 말하기: "반복되는 질문을 먼저 모아 원인을 확인한 뒤, 쉬운 말로 안내문을 만들겠습니다. 이후 문의가 줄었는지 점검하고 필요한 내용을 보완하겠습니다."

다음 꼬리질문: 안내문을 만든 뒤에도 같은 질문이 반복되면 다음에는 어떤 기준으로 개선하실지 말씀해 주세요.
