잘한 점(A 질문 적합성): "개인정보를 지키는 것" — 질문의 핵심인 문서 처리 시 유의점을 첫 문장부터 분명히 제시했습니다.

고칠 점
1. 지켜야 할 원칙만 말해 실제 행동과 확인 절차가 보이지 않습니다. (B 구체성·정확성) 개인정보 보호와 숫자 검증을 각각 어떤 순서와 방법으로 수행하는지 설명해 주세요.
2. 행정직의 문서·민원 업무 및 국민 신뢰와의 연결이 빠졌습니다. (C 직무·기업 연결) 공공기관 행정에서 오류와 개인정보 유출을 예방하는 의미까지 연결해 주세요.

바꿔 말하기: "개인정보를 지키고 숫자를 정확히 확인하는 것이 중요합니다. 문서를 처리할 때는 개인정보가 불필요하게 노출되지 않는지, 숫자와 산출 근거가 맞는지 확인하겠습니다."

