고칠 점
1. 사례와 결과가 없어 보완 효과를 확인하기 어렵습니다. (B 구체성·정확성) 실제로 초안이 늦었던 상황과 이후 달라진 결과를 덧붙여 주세요.
2. 보완 방법이 행정직 업무에 어떻게 도움이 되는지 부족합니다. (C 직무·기업 연결) 문서 작성이나 민원 처리에서 이 방법을 어떻게 적용할지 연결해 주세요.

바꿔 말하기: "저의 단점은 꼼꼼하게 확인하다 보니 초안 작성이 늦어지는 점입니다. 그래서 먼저 초안을 빠르게 만든 뒤 나중에 다듬는 방식으로 보완하고 있으며, 행정 업무에서도 신속성과 정확성을 함께 챙기겠습니다."

