('346dc0b9-66ea-4c82-8d4e-7e68aad502f9',0,$q$1분 동안 자기소개를 해 주세요.$q$,$q$안녕하십니까, 국어국문학과 4학년 문서영입니다. 저는 환자가 이해하기 쉬운 안내를 만드는 일을 해 왔습니다. 병원 안내문을 쉬운 말로 고치는 프로젝트를 했고, 원무팀 실습에서 창구 안내문을 하나로 맞추자고 제안했습니다. 병원행정사 자격증도 땄습니다.$q$,75,'question',$q$총점 75점 · 양호 (A 3 · B 3 · C 3 · D 3 · E 3)

잘한 점(A 질문 적합성): "환자가 이해하기 쉬운 안내" — 자신의 핵심 강점을 첫 부분에 선명하게 제시했습니다.

고칠 점
1. 원무 직무와의 연결은 있으나 실제 업무 기여가 구체적이지 않습니다. (C 직무·기업 연결) 안내문 작성 경험이 접수·민원 안내에 어떻게 도움이 되는지 덧붙여 주세요.
2. 경험의 결과와 본인 역할이 구체적으로 드러나지 않습니다. (B 구체성·정확성) 프로젝트에서 맡은 역할과 개선 결과를 수치로 제시해 주세요.

바꿔 말하기: "저는 환자가 이해하기 쉬운 안내를 만드는 강점이 있습니다. 병원 안내문 개선 프로젝트와 원무팀 실습에서 안내 체계를 정리한 경험을 바탕으로, 원무 업무에서 정확하고 쉬운 안내를 제공하겠습니다."

다음 꼬리질문: 원무팀 실습에서 안내문을 통일할 때 본인이 한 행동과 결과를 구체적으로 말씀해 주세요.
