('346dc0b9-66ea-4c82-8d4e-7e68aad502f9',8,$q$병원 원무 업무에서 진료비 청구가 어떤 흐름으로 이루어지는지 아는 대로 말씀해 주세요.$q$,$q$병원이 본인부담금을 받고 나머지는 심사평가원에 청구하면, 심사 후 건강보험공단이 지급하는 걸로 알고 있습니다.$q$,58,'question',$q$총점 57.5점 · 보완 필요 (A 3 · B 2 · C 2 · D 2 · E 4)

잘한 점(E 전달력·태도): "심사 후 건강보험공단이 지급" — 기관별 지급 흐름을 짧고 이해하기 쉽게 설명했어요.

고칠 점
1. 가중치가 가장 큰 정확성에서 청구 전후 절차가 빠져 감점됐어요. (B 구체성·정확성) 자격 확인→진료비 산정→청구→심사→지급 순서로 핵심 단계를 말해 주세요.
2. 원무 담당자가 실제로 무엇을 확인하는지 연결되지 않았어요. (C 직무·기업 연결) 환자 정보와 본인부담금을 확인하고 오류를 보고하는 적용 예를 덧붙여 주세요.

바꿔 말하기: "병원은 환자 정보를 확인하고 진료비를 산정한 뒤, 본인부담금을 받은 나머지를 심사평가원에 청구합니다. 심사 후 건강보험공단이 지급하는 흐름으로 알고 있습니다."

다음 꼬리질문: 청구 과정에서 환자 정보나 진료비에 오류가 발견되면 무엇부터 확인하고 누구에게 보고할지 말씀해 주세요.
