2. 본인이 실제로 한 행동이나 결과가 없어 설득력이 낮아요. (B 구체성·정확성) 면접에서 말한 경험 중 하나를 행동과 결과 중심으로 짧게 덧붙여 주세요.

바꿔 말하기: "정확하고 쉬운 안내를 드리는 강점을 바탕으로 원무 업무에 기여하겠습니다. 입사 후에도 환자와 보호자가 이해하기 쉬운 안내를 실천하겠습니다."

