('69620975-16a6-42eb-9ff4-ceb1aad75543',0,$q$1분 동안 자기소개를 해 주세요.$q$,$q$안녕하십니까, 국어국문학과 4학년 문서영입니다. 저는 어려운 정보를 쉽게 전하는 일을 잘합니다. 병원 안내문을 쉬운 말로 고치는 프로젝트를 했고, 심사평가원 국민참여 홍보단에서 콘텐츠를 만들어 우수 활동팀에 뽑혔습니다.$q$,61,'question',$q$총점 61.25점 · 보완 필요 (A 3 · B 2 · C 2 · D 3 · E 3)

잘한 점(A 질문 적합성): "어려운 정보를 쉽게 전하는 일을 잘합니다." — 자신의 핵심 강점을 첫 문장에 분명하게 제시했습니다.

고칠 점
1. 행정직에서 어떤 업무에 기여할지 드러나지 않아 직무 연결 점수를 잃었습니다. (C 직무·기업 연결) 안내·문서 작성 경험을 국민 응대와 행정 문서 업무에 연결해 말씀해 주세요.
2. 프로젝트의 본인 역할과 결과가 없어 강점의 근거가 약합니다. (B 구체성·정확성) 담당한 일과 개선 결과를 수치나 구체적 변화로 덧붙여 주세요.

바꿔 말하기: "안녕하십니까, 국어국문학과 4학년 문서영입니다. 저는 어려운 정보를 쉽게 전달하는 강점이 있습니다. 병원 안내문을 고친 프로젝트와 심사평가원 국민참여 홍보단 콘텐츠 제작 경험을 바탕으로, 행정직에서 국민이 이해하기 쉬운 안내와 정확한 문서 업무에 기여하겠습니다."

다음 꼬리질문: 안내문 수정과 홍보단 경험이 건강보험심사평가원 행정직 업무에 어떻게 연결되는지 구체적으로 말씀해 주세요.

확인 필요: 심사평가원 국민참여 홍보단 운영 및 우수 활동팀 선정 사실은 확인 필요 — 확인할 수 없는 사실이라 점수에는 넣지 않았어요.
