잘한 점(E 전달력·태도): "결정은 따르겠습니다." — 답변이 짧고 명확해 전달력이 좋습니다.

고칠 점
1. 부당한 지시인지 확인한 뒤 해결되지 않을 때의 절차가 없어 판단 과정이 불완전합니다. (D 논리 구조) 사실·규정을 확인하고 의견을 제시한 뒤, 필요하면 상위자나 공식 채널에 보고하는 순서로 말해 주세요.
2. 행정직에서 중요한 규정 준수와 국민 편익을 고려했다는 연결이 없습니다. (C 직무·기업 연결) 공공기관 행정 업무의 정확성·공정성·국민 편익을 판단 기준으로 덧붙여 주세요.

바꿔 말하기: "먼저 지시의 목적과 관련 규정을 확인하고, 국민 편익과 규정에 미치는 영향을 검토하겠습니다. 우려되는 점은 근거와 함께 말씀드리고, 해결되지 않으면 상위자나 공식 절차를 통해 협의하겠습니다."

다음 꼬리질문: 상사가 의견을 받아들이지 않고 지시를 강행한다면 어떤 절차로 대응할지 말씀해 주세요.
