잘한 점(A 질문 적합성): "정확함이라고 생각합니다" — 질문에 맞춰 공공기관 직원에게 필요한 자세를 첫 문장에 분명히 답했습니다.

고칠 점
1. 정확함이 행정 업무와 국민 편익에 어떻게 이어지는지 드러나지 않습니다. (C 직무·기업 연결) 자료·문서 확인과 국민에게 정확한 안내를 연결해 말씀해 주세요.
2. 오류를 고친 뒤 어떤 변화가 있었는지 확인하기 어렵습니다. (B 구체성·정확성) 오류를 발견한 과정과 게시 전 수정으로 막은 문제를 덧붙여 주세요.

바꿔 말하기: "공공기관 직원에게 가장 필요한 자세는 정확함이라고 생각합니다. 홍보단에서 게시 전 숫자 오류를 발견해 고친 경험을 바탕으로, 행정 업무에서도 자료와 안내 내용을 꼼꼼히 확인하겠습니다."

다음 꼬리질문: 정확함이 공공기관 행정 업무와 국민 편익에 어떻게 연결되는지 사례를 들어 말씀해 주세요.
