('40649a8f-4960-46be-bd45-c3bc6efafad4',0,$q$1분 동안 자기소개를 해 주세요.$q$,$q$안녕하십니까, 국어국문학과 4학년 문서영입니다. 저는 전공을 살려 병원 안내문을 쉬운 말로 고치는 프로젝트를 했고, 원무팀 실습과 병원행정사 자격으로 원무 업무를 준비했습니다.$q$,69,'question',$q$총점 68.75점 · 보완 필요 (A 3 · B 2 · C 3 · D 3 · E 3)

잘한 점(A 질문 적합성): "전공을 살려 병원 안내문을" — 전공과 경험을 직무와 연결해 자기소개를 시작한 점이 분명합니다.

고칠 점
1. 프로젝트에서 맡은 일과 결과가 없어 경험의 근거가 약합니다. (B 구체성·정확성) 본인 역할과 개선 결과를 수치로 제시해 주세요.
2. 직무 연결은 있으나 지원 분야에서 어떤 강점을 발휘할지 구체성이 부족합니다. (C 직무·기업 연결) 안내문을 쉽게 고친 역량이 환자 안내와 원무 업무에 어떻게 기여하는지 덧붙여 주세요.

바꿔 말하기: "안녕하십니까, 국어국문학과 4학년 문서영입니다. 저는 전공을 살려 병원 안내문을 쉬운 말로 고치는 역량을 길렀습니다. 캡스톤 프로젝트에서 안내문을 개선했고, 원무팀 실습과 병원행정사 자격으로 원무 업무도 준비했습니다. 프로젝트에서 맡은 역할과 결과는 [수치]로 설명드릴 수 있습니다."

다음 꼬리질문: 병원 안내문 프로젝트에서 본인이 맡은 역할과 구체적인 결과를 말씀해 주세요.
