잘한 점(A 질문 적합성): "맞힌 비율을 비교했습니다" — 질문한 측정 방법에 바로 답해 핵심을 분명히 했습니다.

고칠 점
1. 직무 연결이 없어 측정 결과의 활용 가치가 드러나지 않습니다. (C 직무·기업 연결) 원무·안내 업무에서 환자 이해도를 높이는 데 어떻게 활용할지 덧붙여 주세요.
2. 측정의 신뢰성을 보여 줄 문항 수나 비교 결과가 빠졌습니다. (B 구체성·정확성) 문항 수와 수정 전후 결과를 함께 제시해 주세요.

바꿔 말하기: "안내문마다 핵심 내용을 확인하는 문항을 만들고, 수정 전후의 맞힌 비율을 비교했습니다. 이 결과를 바탕으로 환자가 안내를 더 쉽게 이해하는지 확인했습니다."

다음 꼬리질문: 이 측정 방식을 입사 후 원무나 환자 안내 업무에 어떻게 활용할지 말씀해 주세요.
