잘한 점(E 전달력·태도): "쉬운 말로 고쳐 환자 이해도를 높였고" — 핵심 강점과 경험을 짧고 알아듣기 쉽게 전달하셨습니다.

고칠 점
1. 원무 직무에서 강점을 어떻게 활용할지 설명이 부족합니다. (C 직무·기업 연결) 환자 안내와 창구 업무에 어떤 도움을 주는지 한 문장으로 연결해 주세요.
2. 이해도 향상 폭과 안내문 통일 결과가 제시되지 않았습니다. (B 구체성·정확성) 가능한 경우 성과 수치와 본인의 구체적 역할을 함께 말해 주세요.

바꿔 말하기: "저는 환자가 이해하기 쉬운 안내를 만드는 강점이 있습니다. 캡스톤에서 병원 안내문을 쉬운 말로 고쳐 이해도를 [수치]만큼 높였고, 원무팀 실습에서는 창구 안내문을 하나로 맞추자고 제안해 채택시켰습니다. 이 강점으로 원무 업무의 정확한 안내에 기여하겠습니다."

다음 꼬리질문: 두 경험의 강점이 원무 업무에 어떻게 도움이 되는지 구체적으로 말씀해 주세요.
