바꿔 말하기: "홍보단 활동을 하면서 홍보 업무가 재미있어 관심이 생겼습니다. 그 경험에서 맡은 역할과 결과를 바탕으로 홍보·마케팅 직무에 지원했습니다."

다음 꼬리질문: 홍보단에서 본인이 맡은 역할과 그 결과를 구체적으로 말씀해 주세요.
