잘한 점(E 전달력·태도): "글을 잘 쓰는 게 중요" — 핵심 역량을 짧고 분명하게 제시했어요.

고칠 점
1. 전공 수업에서 무엇을 했고 어떤 결과를 냈는지 드러나지 않아요. (B 구체성·정확성) 작성한 과제의 주제·본인 역할·결과를 한 사례로 말해 주세요.
2. 글쓰기 역량이 홍보·마케팅 업무에 어떻게 쓰이는지 부족해요. (C 직무·기업 연결) 고객 메시지 작성이나 콘텐츠 성과와 연결해 설명해 주세요.

바꿔 말하기: "지원 직무에서 가장 중요한 역량은 글쓰기라고 생각합니다. 전공 수업에서 글을 많이 작성하며 준비했고, 그 과정에서 [수치]개의 글을 작성해 [결과]를 얻었습니다. 이 역량을 홍보·마케팅 콘텐츠 작성에 활용하겠습니다."

다음 꼬리질문: 전공 수업에서 글쓰기 역량을 준비한 구체적인 사례와 결과를 말씀해 주세요.
