고칠 점
1. 후기를 어떻게 활용할지와 기대 효과가 없어 실행 가능성을 판단하기 어렵습니다. (B 구체성·정확성) 후기 수집 방식, 전달할 메시지, 확인할 성과를 순서대로 말씀해 주세요.
2. 대학생의 관심사와 지원 직무에서의 기여가 드러나지 않습니다. (C 직무·기업 연결) 대학생에게 맞는 채널과 콘텐츠를 정하고 홍보 성과 측정까지 연결해 주세요.

바꿔 말하기: "대학생이 공감할 수 있는 제품 사용 후기를 모아 소개하겠습니다. 후기에서 반복되는 장점을 중심으로 전달하고, 반응을 확인해 홍보 내용을 보완하겠습니다."

