고칠 점
1. 구체적 기사 내용과 근거가 없어 주장의 설득력이 약합니다. (B 구체성·정확성) 기사에서 본 문제와 실제 영향을 한 가지 덧붙여 주세요.
2. 쉬운 글쓰기와 홍보·마케팅 업무의 연결이 드러나지 않습니다. (C 직무·기업 연결) 고객이 이해하기 쉬운 콘텐츠 제작에 어떻게 적용할지 말해 주세요.

바꿔 말하기: "최근 공공기관 안내문이 어렵다는 기사를 보고, 정보는 누구나 이해할 수 있는 쉬운 말로 전달해야 한다고 생각했습니다. 홍보·마케팅에서도 대상자의 눈높이에 맞춰 메시지를 작성하겠습니다."

다음 꼬리질문: 그 기사에서 안내문이 어렵다고 느낀 구체적인 사례와 홍보·마케팅에 적용할 방법을 말씀해 주세요.

