2. 경험의 구체적인 역할과 결과가 없어 성과를 확인하기 어렵습니다. (B 구체성·정확성) 프로젝트에서 맡은 일과 개선 결과를 수치와 함께 제시해 주세요.

바꿔 말하기: "저는 글을 쉽게 쓰는 역량을 가진 문서영입니다. 홍보단 콘텐츠 제작과 병원 안내문 개선 프로젝트에서 쌓은 경험을 바탕으로, 홍보·마케팅 직무에서 이해하기 쉬운 콘텐츠를 만들겠습니다."

