고칠 점
1. 회사·직무 가중치가 큰데 회사만의 이유가 드러나지 않습니다. (C 직무·기업 연결) 지원 회사의 사업이나 가치와 홍보 직무에서의 기여를 연결해 말씀해 주세요.
