('8c3f6e48-ddce-4fa2-a6f2-e7b088820575',2,$q$우리 회사의 제품이나 서비스 하나를 골라 강점과 개선점을 말씀해 주세요.$q$,$q$즉석밥이 간편한 게 강점인 것 같습니다. 어… 포장 설명이 조금 어려운 것 같습니다.$q$,55,'question',$q$총점 55점 · 보완 필요 (A 3 · B 2 · C 2 · D 2 · E 3)

