2. 홍보·마케팅 직무에서 우선순위를 정하는 방식이 드러나지 않습니다. (C 직무·기업 연결) 캠페인·콘텐츠·문의 대응 중 무엇을 어떤 기준으로 먼저 처리할지 연결해 주세요.

