고칠 점
1. 고객의 가격 우려를 어떻게 판단하고 대응할지 단계가 없어 설득 과정이 보이지 않습니다. (D 논리 구조) 고객의 우선순위 확인→제품 장점과 근거 제시→대안 안내 순서로 말씀해 주세요.
